style.css:
@-moz-document url("https://www.google.com/") {
body {
        background-image: url("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTFJCxN_F0AHHjZfGa6mTYaDljVdXHFscal4A&s");  /* Replace YOUR_IMAGE_URL with the image link */
        background-size: cover;  /* Make the image cover the entire background */
        background-position: center;
        background-repeat: no-repeat;
    }

    /* Hide the Google search bar */
    input[name="q"] {
        display: none;
    }

    /* Hide the Google logo */
    #hplogo {
        display: none;
    }

    /* Style the new 'Jhoanna' text in the center */
    .lnXdpd {
        display: flex;
        justify-content: center;
        align-items: center;
        height: 100vh;  /* Makes it vertically centered */
    }

    /* Replace the Google logo with 'Jhoanna' text */
    .lnXdpd span {
        font-family: 'Arial', sans-serif; /* Choose your preferred font */
        font-size: 70px;  /* Adjust the size to your preference */
        color: #fff;  /* White color for the text */
        font-weight: bold;
        letter-spacing: 5px;  /* Add spacing between letters */
    }
}
